mapper.update:
update clazz
name = #{name}, room = #{room}, begin_date = #{beginDate}, end_date = #{endDate}, master_id = #{masterId}, stage = #{stage}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select c.id, c.name, c.room, c.begin_date as beginDate, c.end_date as endDate, c.master_id as masterId, c.stage, c.create_time as createTime, c.update_time as updateTime, e.name as masterName from clazz c left join emp e on c.master_id = e.id
and c.name like concat('%', #{name}, '%')
and c.begin_date >= #{begin}
and c.end_date <= #{end}
order by c.update_time desc, c.id desc
